.dme-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.dme-root,.dme-root *,.dme-root *::before,.dme-root *::after{box-sizing:border-box}
.dme-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.dme-root img{display:block;border:0;max-width:none}
.dme-root > [data-node-id]{will-change:transform}
.dme-root [hidden]{display:none!important}
.dme-root [data-sh-theme="light"]{display:none!important}
.dme-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.dme-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.dme-root .dme_n2857_3047{position:absolute;align-content:stretch;display:flex;gap:5px;align-items:center;justify-content:center;left:1239px;padding-left:13px;padding-right:13px;padding-top:7px;padding-bottom:7px;border-radius:4px;top:487px;width:152.36px;height:32px;background-image:linear-gradient(-35.693849635041914deg, var(--wa-surface, rgb(48, 49, 61)) 54.212%, var(--wa-surface, rgb(63, 65, 80)) 54.212%)}
.dme-root .dme_n2857_3047::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-line, #434a54);border-radius:4px;pointer-events:none}
.dme-root .dme_nI2857_3047_78_350{position:relative;flex-shrink:0;width:11.363px;height:11.363px}
.dme-root .dme_x1{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.dme-root .dme_nI2857_3047_78_329{word-break:break-word;font-family:"Nanum Gothic","Pretendard",sans-serif;font-weight:700;line-height:18px;font-style:normal;position:relative;flex-shrink:0;font-size:16px;text-align:center;color:var(--wa-text, #fff);white-space:nowrap;width:110px}
.dme-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.dme-root[data-theme="light"] [data-name="Badge/Critical"] p,.dme-root[data-theme="light"] [data-name^="status-critical"] p,.dme-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.dme-root[data-theme="light"] [data-name="Badge/Major"] p,.dme-root[data-theme="light"] [data-name^="status-major"] p,.dme-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.dme-root[data-theme="light"] [data-name="Badge/Minor"] p,.dme-root[data-theme="light"] [data-name^="status-minor"] p,.dme-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.dme-root[data-theme="light"] [data-name="Badge/Warning"] p,.dme-root[data-theme="light"] [data-name^="status-warning"] p,.dme-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.dme-root[data-theme="light"] [data-name="Badge/Normal"] p,.dme-root[data-theme="light"] [data-name^="status-normal"] p,.dme-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.dme-root[data-theme="light"] [data-name="Button/Ack"] p,.dme-root[data-theme="light"] [data-name="Button/Ack All"] p,.dme-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.dme-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.dme-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.dme-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.dme-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.dme-root :is([data-node-id="2857:3067"],[data-node-id="2857:3068"]) > p{line-height:24px!important}
.dme-root :is([data-node-id="2857:3067"],[data-node-id="2857:3068"]){translate:0 -6px}
.dme-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.dme-root > [data-node-id="2857:3044"]{width:1920px;height:1080px}
.dme-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.dme-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.dme-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.dme-root[data-theme="light"] [data-name="Symbol"] > [data-name="Shape"] img{opacity:.32;filter:saturate(.7)}
.dme-root[data-theme="light"] :is([data-name="Floor Layer"],[data-name="Floor"] > [data-name="Part"]) > *{opacity:.18}
.dme-root[data-theme="light"] [data-name="Floor"] img{opacity:.25}
.dme-root[data-theme="light"] [data-name="Effect"] > * > *,.dme-root[data-theme="light"] [data-name="Effect"] img{opacity:.45}
.dme-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.dme-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.dme-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1668d4)!important}
.dme-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.dme-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.dme-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.dme-root[data-theme="light"] .dme_n2857_3047{background-image:linear-gradient(transparent,transparent)}
.dme-root[data-theme="light"] .dme_n2857_3047::after{border-color:var(--wa-line, #bfc2c8)}
.dme-root[data-theme="light"] .dme_nI2857_3047_78_329{color:var(--wa-point, #0f2238)}
.dme-root[data-theme="light"] [data-node-id="2857:3046"]{box-shadow:0 18px 44px rgba(20,45,80,.26),0 2px 8px rgba(20,45,80,.12)!important}
.dme-root[data-theme="light"] [data-node-id="2857:3046"]::after{border-color:var(--wa-line, #a9b9cd)!important}
.dme-root[data-theme="light"] [data-node-id="2857:3049"]{background-image:linear-gradient(to right,var(--wa-bg, #e4ebf4) 48.714%,var(--wa-point, #bccbdd))!important;box-shadow:inset 0 -1px 0 #b3c3d6}
.dme-root[data-theme="light"] [data-node-id="2857:3063"]{background-color:var(--wa-bg, #f1f5fa)!important}
